const ESCRITURA = [
  {ref:`Juan 3:5`, d:`"El que no naciere de agua y del Espíritu, no puede entrar en el reino de Dios." Para la Iglesia, Jesús habla del agua del bautismo, y no en sentido metafórico {c:T7b2|Trento, ses. VII, Del bautismo, can. 2}; por eso el bautismo es necesario para la salvación {c:CEC1257|Catecismo 1257}.`},
  {ref:`Mateo 28:19-20; Marcos 16:15-16`, d:`"Por tanto, id, y doctrinad á todos los Gentiles, bautizándolos en el nombre del Padre, y del Hijo, y del Espíritu Santo." Para el Catecismo, es el mandato del Señor {c:CEC1257|Catecismo 1257}; y por Marcos 16:16, "El que creyere y fuere bautizado, será salvo", llama al bautismo "el sacramento de la fe" {c:CEC1253|Catecismo 1253}.`,
   rv:`«Por tanto, id…» restaurado según RV1909 (verificación 2, C2).`},
  {ref:`Hechos 2:38`, d:`"Arrepentíos, y bautícese cada uno de vosotros en el nombre de Jesucristo para perdón de los pecados; y recibiréis el don del Espíritu Santo." Para el Catecismo, son los dos efectos del bautismo: el perdón de los pecados y el nuevo nacimiento en el Espíritu {c:CEC1262|Catecismo 1262}.`,
   rv:`La nota de Waterworth «Acts ii. 38» en Trento XIV cap. 1 (p. 93) se confirmó en la verificación 2 (A14).`},
  {ref:`Romanos 6:3-4; Colosenses 2:12`, d:`"Somos bautizados en su muerte… somos sepultados juntamente con él á muerte por el bautismo": para el Catecismo, la inmersión simboliza esa sepultura y esa resurrección {c:CEC1214|Catecismo 1214}, y por el bautismo el creyente "es sepultado y resucita con Él" {c:CEC1227|Catecismo 1227}.`},
  {ref:`Tito 3:5`, d:`"Por el lavacro de la regeneración, y de la renovación del Espíritu Santo": para el Catecismo, el bautismo "significa y realiza" ese nuevo nacimiento {c:CEC1215|Catecismo 1215}.`},
  {ref:`Gálatas 3:27`, d:`"Todos los que habéis sido bautizados en Cristo, de Cristo estáis vestidos": el Catecismo lo cita para la vestidura blanca del rito {c:CEC1243|Catecismo 1243}, y Trento, para la "plena y entera remision de los pecados" que atribuye al bautismo {c:T14c2|ses. XIV, cap. 2}.`},
  {ref:`1 Corintios 6:11; 12:13`, d:`"mas [ya] sois lavados, mas [ya] sois santificados, mas [ya] sois justificados"; "por un Espíritu somos todos bautizados en un cuerpo": para el Catecismo, el bautismo "es un baño que purifica, santifica y justifica" {c:CEC1227|Catecismo 1227} y nos hace "miembros del Cuerpo de Cristo" {c:CEC1267|Catecismo 1267}.`,
   rv:`«mas [ya] sois lavados…» restaurado según RV1909 (verificación 2, C2).`},
  {ref:`Romanos 5:12`, d:`"El pecado entró en el mundo por un hombre": para Trento, este texto, leído como lo leyó siempre la Iglesia, es la razón por la que también los niños se bautizan "en remisión de los pecados" {c:T5can4|ses. V, can. 4}.`},
  {ref:`Hechos 16:15, 33; 18:8; 1 Corintios 1:16`, d:`Casas enteras recibieron el bautismo: el Catecismo considera "muy posible" que desde la predicación apostólica se bautizara también a los niños {c:CEC1252|Catecismo 1252}.`},
  {ref:`Marcos 10:14`, d:`"Dejad los niños venir, y no se lo estorbéis": el Catecismo lo cita para la comunión de los niños en Oriente y para la esperanza sobre los niños que mueren sin bautismo {c:CEC1244|Catecismo 1244} {c:CEC1261|Catecismo 1261}.`},
  {ref:`1 Pedro 3:20`, d:`El Catecismo lee el arca de Noé, en la que "unos pocos […] fueron salvados a través del agua", como prefiguración de la salvación por el bautismo {c:CEC1219|Catecismo 1219}.`},
  {ref:`1 Pedro 3:21`, d:`El Catecismo cita este versículo para decir que "el diluvio y el arca de Noé prefiguraban la salvación por el Bautismo" {c:CEC1094|Catecismo 1094}, y ve la Iglesia "prefigurada por el Arca de Noé que es la única que salva del diluvio" {c:CEC845|Catecismo 845}.`},
  {ref:`Efesios 4:30; 1:13-14; 2 Corintios 1:21-22`, d:`Para el Catecismo, el sello "para el día de la redención" es el carácter bautismal, que no se borra y no se repite {c:CEC1274|Catecismo 1272–1274}.`},
  {ref:`1 Timoteo 2:4`, d:`Dios "quiere que todos los hombres sean salvos": el Catecismo lo cita como razón de que, en caso de necesidad, cualquiera pueda bautizar, y de su confianza en "un camino de salvación para los niños que mueren sin Bautismo" {c:CEC1256|Catecismo 1256} {c:CEC1261|Catecismo 1261}.`},
  {ref:`Juan 19:34; Marcos 10:38`, d:`Para el Catecismo, la sangre y el agua del costado de Cristo son figuras del bautismo y de la Eucaristía: el bautismo viene "de la cruz de Cristo, de la muerte de Cristo" {c:CEC1225|Catecismo 1225, citando a san Ambrosio}.`},
  {ref:`Mateo 3:13-17`, d:`Jesús se somete al bautismo de Juan y el Espíritu desciende sobre él: el Catecismo lo lee como "preludio de la nueva creación" {c:CEC1223|Catecismo 1224}.`},
  {ref:`1 Pedro 2:5, 9`, d:`"Como piedras vivas, sed edificados una casa espiritual, y un sacerdocio santo"; "linaje escogido, real sacerdocio": el Catecismo lo cita para decir que por el bautismo los fieles "participan del sacerdocio de Cristo" {c:CEC1268|Catecismo 1268}.`, rv:`Añadido con QE-11 en el paso de correcciones del 2026-10-18.`},
  {ref:`Efesios 4:25`, d:`"[…] somos miembros los unos de los otros": el Catecismo lo cita para decir que el bautismo "hace de nosotros miembros del Cuerpo de Cristo" {c:CEC1267|Catecismo 1267}.`, rv:`Añadido con QE-11 en el paso de correcciones del 2026-10-18. Las palabras citadas son las del Catecismo 1267; el dosier no las pasó a la RV1909.`},
  {ref:`Gálatas 5:3`, d:`El bautizado queda obligado "a toda la ley de Cristo", no solo a la fe {c:T7b7|Trento, ses. VII, Del bautismo, can. 7}.`, rv:`Trento no cita el versículo en el texto: es la nota de Waterworth al canon (p. 56).`}
];

const VIVE = {
  intro:[
    `Para la Iglesia católica, el bautismo es la puerta de la vida cristiana, y su ley pide a los padres que hagan bautizar a sus hijos "en las primeras semanas" {c:CIC867a|Código de Derecho Canónico, can. 867}. El adulto que pide el bautismo recorre antes un catecumenado y recibe en una sola celebración el bautismo, la confirmación y la Eucaristía {c:CEC1232|Catecismo 1233}.`,
    `La Iglesia celebra el bautismo con signos que, según el Catecismo, muestran lo que el sacramento realiza: la señal de la cruz, la Palabra de Dios, la renuncia a Satanás y la profesión de fe, el agua bendecida, la triple inmersión o la infusión con la invocación de la Trinidad, la unción con el crisma, la vestidura blanca y el cirio encendido en el cirio pascual {c:CEC1234|Catecismo 1234–1245}. En caso de necesidad, cualquier persona puede bautizar {c:CIC861|can. 861}.`
  ],
  items:[
    {id:`CV-1`, l:`Bautismo de los niños`, d:`Los padres «tienen obligación de hacer que los hijos sean bautizados en las primeras semanas»; si el niño está en peligro de muerte, «debe ser bautizado sin demora». Para bautizarlo lícitamente se pide el consentimiento de al menos uno de los padres y la «esperanza fundada» de que será educado en la fe católica; si falta por completo, se difiere y se explica a los padres por qué.`, s:[[`CIC867`,`Código de Derecho Canónico, cann. 867, 868 §1`],[`CEC1250,CEC1251`,`Catecismo 1250–1251`]],
     rv:`Can. 868 §2 (en peligro de muerte, «aun contra la voluntad de sus padres»): fuera mientras CV-1 diga «lícitamente»; Pregunta 15.`},
    {id:`CV-2`, l:`Padres y padrinos`, d:`Antes del bautismo, padres y padrinos han de ser «convenientemente ilustrados sobre el significado de este sacramento». El padrino ayuda al bautizado a llevar «una vida cristiana congruente con el bautismo»; uno o una, o uno y una; ha de tener dieciséis años (salvo otra norma del obispo), ser católico, confirmado y haber recibido la Eucaristía, y no ser el padre o la madre. Un bautizado de otra comunidad cristiana solo puede ser testigo, junto a un padrino católico.`, s:[[`CIC851`,`cann. 851 2°, 872–874`],[`CEC1255`,`Catecismo 1255`]]},
    {id:`CV-3`, l:`Adultos: el catecumenado`, d:`El adulto es admitido al catecumenado y llevado «por pasos sucesivos» a la iniciación; debe manifestar su deseo, estar instruido y «probado en la vida cristiana». Los catecúmenos «están ya unidos a la Iglesia». Bautizado, debe ser confirmado inmediatamente y recibir la comunión en la misma celebración.`, s:[[`CIC851a`,`cann. 851 1°, 865 §1, 866`],[`CEC1232,CEC1247`,`Catecismo 1232–1233, 1247–1249`],[`SC64`,`Sacrosanctum Concilium 64`]]},
    {id:`CV-4`, l:`El rito y sus signos`, d:`La señal de la cruz; la Palabra; uno o varios exorcismos y la unción con el óleo de los catecúmenos; la renuncia a Satanás y la profesión de fe; la bendición del agua con una oración de epíclesis; el bautismo; la unción con el santo crisma; la vestidura blanca y el cirio; el Padre Nuestro; la bendición final.`, s:[[`CEC1234`,`Catecismo 1234–1245`]]},
    {id:`CV-5`, l:`Inmersión o infusión, y la fórmula`, d:`«El bautismo se ha de administrar por inmersión o por infusión […]»; en la Iglesia latina, con las palabras «N., yo te bautizo en el nombre del Padre, y del Hijo y del Espíritu Santo»; en Oriente, «El siervo de Dios, N., es bautizado…». La fórmula no se cambia: el Dicasterio para la Doctrina de la Fe recordó en 2024 que bautismos celebrados con «nosotros te bautizamos» u otras fórmulas fueron nulos y hubo que repetirlos.`, s:[[`CIC846`,`cann. 854, 846 §1`],[`CEC1239`,`Catecismo 1239–1240`],[`GV`,`Gestis verbisque (2024)`]],
     rv:`Hueco del mapa 2: la nota de la Congregación de 2020 sobre la fórmula no está en el mapa; CV-5 se apoya en Gestis verbisque, que sí está.`},
    {id:`CV-6`, l:`En caso de necesidad`, d:`Si falta el ministro ordinario, bautiza un catequista designado y, en caso de necesidad, «cualquier persona que tenga la debida intención»; basta derramar agua sobre la cabeza y decir «Yo te bautizo en el nombre del Padre y del Hijo y del Espíritu Santo». Los párrocos han de procurar que los fieles «sepan bautizar debidamente».`, s:[[`CIC861`,`can. 861 §2`],[`CEC1256`,`Catecismo 1256`],[`CEC1284`,`Catecismo 1284`]]},
    {id:`CV-7`, l:`Una sola vez`, d:`El bautismo «no puede reiterarse». Si hay duda razonable de que alguien fue bautizado válidamente, se bautiza «bajo condición»; a quienes fueron bautizados en otra comunidad cristiana no se los bautiza de nuevo, salvo «un motivo serio para dudar» de la materia, la fórmula o la intención.`, s:[[`CIC845`,`cann. 845, 869`],[`CEC1272`,`Catecismo 1272`]]},
    {id:`CV-8`, l:`Cuándo y dónde`, d:`Puede celebrarse cualquier día, pero de ordinario conviene el domingo o, si es posible, la Vigilia Pascual; fuera del caso de necesidad, el lugar propio es «una iglesia u oratorio», y como norma general la iglesia parroquial, que ha de tener pila bautismal; no en casas particulares ni hospitales salvo necesidad o permiso.`, s:[[`CIC856`,`cann. 856–860`]]},
    {id:`CV-9`, l:`Nombre y registro`, d:`Padres, padrinos y párroco procuran «que no se imponga un nombre ajeno al sentir cristiano»; el párroco anota el bautismo en el libro de bautismo, con ministro, padres, padrinos, lugar y día.`, s:[[`CIC855`,`cann. 855, 877`]]},
    {id:`CV-10`, l:`Renovar las promesas`, d:`«En todos los bautizados, niños o adultos, la fe debe crecer después del Bautismo. Por eso, la Iglesia celebra cada año en la vigilia pascual la renovación de las promesas del Bautismo.» El bautizado tiene deberes y derechos en la Iglesia: recibir los sacramentos y la palabra de Dios, y confesar la fe.`, s:[[`CEC1254`,`Catecismo 1254`],[`CEC1269`,`Catecismo 1269–1270`]]},
    {id:`CV-11`, l:`Confirmación y primera comunión`, d:`En los ritos orientales, el niño recibe juntos bautismo, confirmación (crismación) y Eucaristía; en el rito romano la iniciación de los niños «se continúa durante unos años de catequesis» y culmina más tarde con la confirmación y la Eucaristía; el bautizado se acerca al altar para el Padre Nuestro.`, s:[[`CEC1232`,`Catecismo 1233`],[`CEC1244`,`Catecismo 1244`],[`CIC842`,`Código de Derecho Canónico, can. 842 §2`]]},
    {id:`CV-12`, l:`Niños que mueren sin bautismo`, d:`La Iglesia los confía «a la misericordia divina», también en el rito de exequias por ellos, y la liturgia invita «a orar por su salvación». La misericordia de Dios y la ternura de Jesús con los niños «nos permiten confiar en que haya un camino de salvación para los niños que mueren sin Bautismo»; por eso, dice el Catecismo, es «más apremiante aún» no impedir que los niños vengan a Cristo por el bautismo.`, s:[[`CEC1261`,`Catecismo 1261`],[`CEC1283`,`Catecismo 1283`]],
     rv:`Revisado en el paso de correcciones (experto 3a).`}
  ]
};

const OB_ORDER = [`DO-3`,`DO-5`,`DO-7`,`OB-1`,`OB-2`,`DO-1`,`DO-2`,`DO-4`,`DO-6`,`OB-6a`,`OB-6b`,`OB-4`,`OB-3`,`OB-5`];

const RV_FLO = `La cita de Florencia en español es traducción asistida por IA (sin revisar por Pedro), desde el latín de Mansi.`;
const RV_PEND = `Nota marcada «Respuesta apologética pendiente (capa de debate)»: no es texto de la respuesta; el punto va a la investigación de debate (DECISIONS 2026-10-20). No se escribió contenido apologético.`;
const RV_DEB = `Capa de debate (DECISIONS 2026-10-20, «Baptism: the debate objections that stay»): título tal como Pedro lo aprobó; anclas en el texto oficial de la tradición que objeta; los debatientes van solo en la ventana de fuentes, nunca su nombre en la página. Respuesta solo con textos católicos citados, leídos el 2026-10-21, y final en el canon que corresponde.`;
const RV_LINE = `La línea «Desde la tradición … se objeta que…» es la «línea de la página 04» del dosier. Aquí va en el lugar de «quién la plantea», debajo del recuadro; el dosier la pone antes de la síntesis, que solo se sostiene bajo esa línea (verificación 2, G7).`;
const WHO_ORTH = `El Oros de 1755 de los patriarcas de Constantinopla, Alejandría y Jerusalén recibe "como no bautizados" a quienes vienen bautizados de otro modo. El mapa ortodoxo registra su aplicación como "contested".`;
const RV_WHO_ORTH = `Línea del dosier para la pantalla 04, común a OB-6a y OB-6b (Pregunta 5, abierta). Corregida el 2026-10-21, igual que ST-OROS (verificación 2, D8): ya no opone Dositeo XV al Oros ni dice que cada Iglesia ortodoxa sigue su práctica. Las palabras entre comillas son traducción asistida por IA, sin revisar por Pedro, salvo "contested", palabra del mapa ortodoxo que queda en inglés dentro del borrador (elección de Pedro). Constantinopla 1484 y Moscú 1667 quedan fuera hasta leerlos en una edición.`;

const OBJ = {
  'DO-3': {title:`«El bautismo no salva: lo que salva es la sangre de Cristo» — Frecuente en el debate`,
    syn:`Lo que salva es la sangre de Cristo, recibida por la fe; el agua no tiene poder para perdonar pecados. El bautismo es un acto de obediencia y un testimonio público de una salvación ya recibida, como el anillo no es lo que casa a nadie. Hay bautizados que se perdieron.`,
    who:`Desde las Asambleas de Dios y desde la tradición bautista se objeta que el bautismo no salva, porque solo salva la sangre de Cristo, recibida por la fe. Para las Asambleas de Dios, "la única esperanza de redención para el hombre es a través de la sangre derramada de Jesucristo, el Hijo de Dios" (Declaración de Verdades Fundamentales, 5); para los bautistas, "no hay salvación aparte de la fe personal en Jesucristo como Señor" (Fe y Mensaje Bautistas, art. IV).`,
    own:{lead:[`AG5`], more:[`BFM4`,`BFM7c`,`AG6d`]},
    answer:[
      `El Catecismo dice: "La justificación nos fue merecida por la pasión de Cristo, que se ofreció en la cruz como hostia viva, santa y agradable a Dios y cuya sangre vino a ser instrumento de propiciación por los pecados de todos los hombres. La justificación es concedida por el Bautismo, sacramento de la fe" {c:CEC1992|Catecismo 1992}.`,
      `El Catecismo dice que el bautismo nace de la cruz: "La sangre y el agua que brotaron del costado traspasado de Jesús crucificado (cf. Jn 19,34) son figuras del Bautismo y de la Eucaristía", y cita a san Ambrosio (_Sobre los sacramentos_, c. 387–391): "Considera dónde eres bautizado, de dónde viene el Bautismo: de la cruz de Cristo, de la muerte de Cristo. Ahí está todo el misterio: Él padeció por ti. En él eres rescatado, en él eres salvado" {c:CEC1225|Catecismo 1225}.`,
      `Para la Iglesia católica, quien obra en el bautismo es Cristo: los sacramentos "son eficaces porque en ellos actúa Cristo mismo; Él es quien bautiza" {c:CEC1127|Catecismo 1127}, y obran "en virtud de la obra salvífica de Cristo, realizada de una vez por todas" {c:CEC1128|Catecismo 1128}. El Catecismo llama al bautismo "baño de regeneración y de renovación del Espíritu Santo" (Tt 3,5) {c:CEC1215|Catecismo 1215}, y dice que es "una gracia y un don de Dios que no suponen méritos humanos" {c:CEC1282|Catecismo 1282}.`,
      `Sobre los bautizados que se pierden, el Catecismo dice: "los frutos de los sacramentos dependen también de las disposiciones del que los recibe" {c:CEC1128|Catecismo 1128}, y el pecado puede impedir "al Bautismo dar frutos de salvación" {c:CEC1272|Catecismo 1272}. Y sobre su necesidad: "El Señor mismo afirma que el Bautismo es necesario para la salvación (cf Jn 3,5) […] Dios ha vinculado la salvación al sacramento del Bautismo, sin embargo, Él no queda sometido a sus sacramentos" {c:CEC1257|Catecismo 1257}.`,
      `El canon de Trento dice: "Si alguno dixere, que el Bautismo es arbitrario, esto es, no preciso para conseguir la salvacion; sea excomulgado" {c:T7b5|ses. VII, Del bautismo, can. 5}.`
    ],
    answerRv:{0:`Abre con las palabras del Catecismo 1992 («justificación»), no con una frase del sitio sobre «la salvación» (verificación 2, G4).`, 1:`Fecha de Ambrosio junto a su nombre (Pedro, 2026-10-20): mapa neutral writers-latin; autoría discutida en otro tiempo.`, 3:`El argumento del anillo de boda no lo responde ningún texto leído; el de «una obra» (Tito 3:5) lo responden Catecismo 1215 y 1282, como se citan.`},
    fuentes:[
      {ids:`CEC1127,CEC1128,CEC1215,CEC1225,CEC1257,CEC1272,CEC1282,CEC1992`, name:`Catecismo de la Iglesia Católica 1127, 1128, 1215, 1225, 1257, 1272, 1282, 1992`, date:`1992/1997`, year:1992},
      {ids:`T7b5`, name:`Concilio de Trento, sesión VII, Del bautismo, can. 5`, date:`3 mar 1547`, year:1547}
    ],
    pasajes:{resp:[`Juan 19:34`,`Tito 3:5`,`Juan 3:5`], obj:[`Tito 3:5`,`1 Corintios 10:5`,`1 Timoteo 1:19-20`], objNote:`Versículos citados en los debates.`},
    rv:[RV_DEB, RV_LINE, `Dónde se plantea (ventana de fuentes, no va en la página): 11 como mucho (8 firmes, 1 parcial, 2 escritos); en español y en inglés. Detalle en el dosier (F-5, D-1).`, `Anclas: Asambleas de Dios 5 a la vista; en «ver más», Fe y Mensaje Bautistas IV y VII, y Asambleas de Dios 6.`]},

  'DO-5': {title:`«Los versículos que citan los católicos no enseñan que el bautismo salve» — Frecuente en el debate`,
    syn:`Los versículos que se citan para decir que el bautismo salva {v:Hechos 2:38} {v:1 Pedro 3:21} {v:Marcos 16:16} {v:Juan 3:5}, leídos en su contexto, no hacen del bautismo el medio de la salvación; y Pablo distingue el bautismo del evangelio {v:1 Corintios 1:17}.`,
    who:`Desde la tradición bautista se objeta que los versículos con que la Iglesia católica funda el poder salvador del bautismo, leídos en su contexto, no lo enseñan. Para los bautistas, el bautismo es "un acto de obediencia que simboliza la fe del creyente" (Fe y Mensaje Bautistas, art. VII), y "no hay salvación aparte de la fe personal en Jesucristo como Señor" (art. IV).`,
    own:{lead:[`BFM7c`], more:[`BFM4b`]},
    answer:[
      `{v:Hechos 2:38} «bautícese cada uno de vosotros en el nombre de Jesucristo para perdón de los pecados». Desde la tradición bautista se lee: «"Para perdón" quiere decir "a causa del perdón" ya recibido por la fe.»`,
      `El Catecismo cita este versículo para el bautismo que la Iglesia administra desde Pentecostés {c:CEC1226|Catecismo 1226}, y dice: "Los dos efectos principales, por tanto, son la purificación de los pecados y el nuevo nacimiento en el Espíritu Santo (cf Hch 2,38; Jn 3,5)" {c:CEC1262|Catecismo 1262}. _Respuesta apologética pendiente (capa de debate):_ el sentido de la preposición griega (_eis_).`,
      `{v:1 Pedro 3:21} «el bautismo que ahora corresponde nos salva (no quitando las inmundicias de la carne…)». Desde la tradición bautista se lee: «Lo que salvó a Noé fue el arca, no el agua; y Pedro aclara que no salva el lavado del cuerpo.»`,
      `El Catecismo dice: "el diluvio y el arca de Noé prefiguraban la salvación por el Bautismo (cf 1 P 3, 21)" {c:CEC1094|Catecismo 1094}; "La Iglesia ha visto en el arca de Noé una prefiguración de la salvación por el bautismo. En efecto, por medio de ella 'unos pocos, es decir, ocho personas, fueron salvados a través del agua' (1 P 3,20)" {c:CEC1219|Catecismo 1219}; y la Iglesia "está prefigurada por el Arca de Noé que es la única que salva del diluvio (cf 1 P 3, 20-21)" {c:CEC845|Catecismo 845}. _Respuesta apologética pendiente (capa de debate):_ la lectura de "no quitando las inmundicias de la carne".`,
      `{v:Marcos 16:16} «El que creyere y fuere bautizado, será salvo; mas el que no creyere, será condenado». Desde la tradición bautista se lee: «Solo se condena al que no cree; el bautismo no es condición de salvación.»`,
      `El Catecismo dice: "El Bautismo es necesario para la salvación en aquellos a los que el Evangelio ha sido anunciado y han tenido la posibilidad de pedir este sacramento (cf Mc 16,16)" {c:CEC1257|Catecismo 1257}, y "El Bautismo es el sacramento de la fe (cf Mc 16,16)" {c:CEC1253|Catecismo 1253}. _Respuesta apologética pendiente (capa de debate):_ el argumento de que la segunda mitad del versículo no nombra el bautismo, y la autenticidad del final de Marcos.`,
      `{v:Juan 3:5} «el que no naciere de agua y del Espíritu, no puede entrar en el reino de Dios». Desde la tradición bautista se lee: «El agua no es el bautismo: es la Palabra, o el nacimiento natural; el texto no dice "bautismo".»`,
      `Trento manda no torcer estas palabras "á algun sentido metafórico" {c:T7b2|ses. VII, Del bautismo, can. 2}. El Catecismo llama al bautismo "'baño de regeneración y de renovación del Espíritu Santo' (Tt 3,5), porque significa y realiza ese nacimiento del agua y del Espíritu sin el cual 'nadie puede entrar en el Reino de Dios' (Jn 3,5)" {c:CEC1215|Catecismo 1215}, y dice que desde la cruz "es posible 'nacer del agua y del Espíritu' para entrar en el Reino de Dios" {c:CEC1225|Catecismo 1225}.`,
      `{v:1 Corintios 1:17} «no me envió Cristo á bautizar, sino á predicar el evangelio». Desde la tradición bautista se lee: «Pablo no consideraba el bautismo parte del evangelio.»`,
      `_Respuesta apologética pendiente (capa de debate):_ ningún texto católico leído cita este versículo.`,
      `{v:Tito 3:5} «No por obras de justicia que nosotros habíamos hecho, mas por su misericordia nos salvó». Desde la tradición bautista se lee: «El bautismo es una obra, y no somos salvos por obras.»`,
      `El Catecismo cita este versículo para el bautismo: "baño de regeneración y de renovación del Espíritu Santo" {c:CEC1215|Catecismo 1215}; y dice que el bautismo es "una gracia y un don de Dios que no suponen méritos humanos" {c:CEC1282|Catecismo 1282}.`,
      `El canon de Trento dice: "Si alguno dixere, que el agua verdadera y natural no es necesaria para el Sacramento del Bautismo, y por este motivo torciere á algun sentido metafórico aquellas palabras de nuestro señor Jesu-Cristo: 'Quien no renaciere del agua, y del Espíritu Santo;' sea excomulgado" {c:T7b2|ses. VII, Del bautismo, can. 2}.`
    ],
    answerRv:{0:`El dosier da una tabla (versículo · relectura que se escucha · respuesta católica). Esta maqueta no tiene tabla: cada fila va como dos párrafos, la relectura introducida «Desde la tradición bautista se lee…» y luego la respuesta (Pregunta 20). Las relecturas son síntesis neutrales del agente, no palabras de un debatiente.`, 1:RV_PEND, 3:RV_PEND, 5:RV_PEND, 9:`${RV_PEND} La verificación 2 (B11) confirma que ninguno de los textos católicos leídos cita 1 Corintios 1:17.`, 10:`Sexto versículo: va más allá de los cinco que Pedro nombró en DECISIONS 2026-10-20 y se apoya en un solo debatiente (Pregunta 20, mantenerlo o quitarlo).`, 12:`Final: el can. 2 es el único canon que se pronuncia sobre cómo se lee uno de estos versículos.`},
    fuentes:[
      {ids:`CEC845,CEC1094,CEC1215,CEC1219,CEC1225,CEC1226,CEC1253,CEC1257,CEC1262,CEC1282`, name:`Catecismo de la Iglesia Católica 845, 1094, 1215, 1219, 1225, 1226, 1253, 1257, 1262, 1282`, date:`1992/1997`, year:1992},
      {ids:`T7b2`, name:`Concilio de Trento, sesión VII, Del bautismo, can. 2`, date:`3 mar 1547`, year:1547}
    ],
    pasajes:{resp:[], obj:[`Hechos 2:38`,`1 Pedro 3:20-21`,`Marcos 16:16`,`Juan 3:5`,`1 Corintios 1:17`,`Tito 3:5`], objNote:`El dosier los da como «objeción y respuesta»: cada versículo está en las dos.`},
    rv:[RV_DEB, RV_LINE, `Dónde se plantea (ventana de fuentes, no va en la página): 6 independientes, agrupados por decisión de Pedro (F-8).`, `Anclas: ningún texto ancla lee estos versículos; las Asambleas de Dios 6 citan Marcos 16:16 como prueba del mandato, no contra él, así que no se las nombra aquí.`]},

  'DO-7': {title:`«El ladrón en la cruz no se bautizó» — Frecuente en el debate`,
    syn:`El ladrón arrepentido no fue bajado de la cruz para bautizarse, y Jesús le dijo: "De cierto te digo, que hoy estarás conmigo en el paraíso" {v:Lucas 23:43}. Otros recibieron el perdón o el Espíritu sin bautismo (el paralítico, el publicano, Cornelio, {v:Hechos 10:47}). La salvación es por la fe, no por el bautismo.`,
    who:`Desde la tradición bautista y desde las Asambleas de Dios se objeta que el bautismo no es necesario para salvarse, como muestra el ladrón en la cruz. Para los bautistas, "no hay salvación aparte de la fe personal en Jesucristo como Señor" (Fe y Mensaje Bautistas, art. IV); para las Asambleas de Dios, "la salvación se recibe a través del arrepentimiento para con Dios y la fe en el Señor Jesucristo" (Declaración de Verdades Fundamentales, 5).`,
    own:{lead:[`BFM4b`], more:[`AG5b`]},
    answer:[
      `El Catecismo dice: "El Bautismo es necesario para la salvación en aquellos a los que el Evangelio ha sido anunciado y han tenido la posibilidad de pedir este sacramento (cf Mc 16,16) […] Dios ha vinculado la salvación al sacramento del Bautismo, sin embargo, Él no queda sometido a sus sacramentos" {c:CEC1257|Catecismo 1257}.`,
      `Trento enseña que el paso al estado de gracia "no se puede lograr, despues de promulgado el Evangelio, sin el Bautismo, ó sin el deseo de él" {c:T6c4|ses. VI, cap. 4}.`,
      `El Catecismo dice: "quienes padecen la muerte por razón de la fe, sin haber recibido el Bautismo, son bautizados por su muerte con Cristo y por Cristo. Este Bautismo de sangre como el deseo del Bautismo, produce los frutos del Bautismo sin ser sacramento" {c:CEC1258|Catecismo 1258}; "A los catecúmenos que mueren antes de su Bautismo, el deseo explícito de recibir el Bautismo, unido al arrepentimiento de sus pecados y a la caridad, les asegura la salvación que no han podido recibir por el sacramento" {c:CEC1259|Catecismo 1259}; y "Todo hombre que, ignorando el Evangelio de Cristo y su Iglesia, busca la verdad y hace la voluntad de Dios según él la conoce, puede ser salvado" {c:CEC1260|Catecismo 1260}.`,
      `_Respuesta apologética pendiente (capa de debate):_ el caso del ladrón en la cruz, que estos textos no nombran, y los de Cornelio, el paralítico y el publicano.`,
      `El canon de Trento dice: "Si alguno dixere, que el Bautismo es arbitrario, esto es, no preciso para conseguir la salvacion; sea excomulgado" {c:T7b5|ses. VII, Del bautismo, can. 5}.`
    ],
    answerRv:{2:`La respuesta aplica el principio de Catecismo 1257–1260 y no dice que alcance al ladrón: esa aplicación es el punto pendiente (verificación 2, B10 y G2: ninguno de los nn. 1257–1261 nombra al ladrón).`, 3:RV_PEND},
    fuentes:[
      {ids:`CEC1257,CEC1258,CEC1259,CEC1260`, name:`Catecismo de la Iglesia Católica 1257–1260`, date:`1992/1997`, year:1992},
      {ids:`T6c4`, name:`Concilio de Trento, sesión VI, cap. 4`, date:`13 ene 1547`, year:1547},
      {ids:`T7b5`, name:`Concilio de Trento, sesión VII, Del bautismo, can. 5`, date:`3 mar 1547`, year:1547}
    ],
    pasajes:{resp:[`Marcos 16:16`], obj:[`Lucas 23:39-43`,`Hechos 10:44-48`], objNote:`Versículos citados en los debates.`},
    rv:[RV_DEB, RV_LINE, `Título en inglés (BSB, Lucas 23:43): "The thief on the cross was not baptized" (los debatientes añaden "today you will be with Me in Paradise").`, `Dónde se plantea (ventana de fuentes, no va en la página): 6 independientes sobre el ladrón (5 sin el oyente que llama); Cornelio, 4 (F-6, D-2).`, `Anclas solo por inferencia: ninguna nombra al ladrón.`]},

  'OB-1': {title:`«La gracia y la salvación no están tan unidas al bautismo que nadie pueda salvarse sin él, ni todos los bautizados quedan regenerados»`,
    syn:`El bautismo es "signo y sello" del pacto de gracia, de la incorporación a Cristo, de la regeneración y del perdón de los pecados {c:WCF281|Confesión de Westminster XXVIII.1}. Despreciarlo o descuidarlo es un grave pecado, pero la gracia y la salvación no están tan unidas a él que nadie pueda ser regenerado o salvado sin bautismo, ni todos los bautizados quedan por eso regenerados: Simón el mago fue bautizado y seguía "en hiel de amargura" {v:Hechos 8:13, 23}. La eficacia del bautismo no está atada al momento en que se administra; el Espíritu da la gracia prometida a quienes pertenece, según el consejo de Dios y en el tiempo que él dispone.`,
    who:`Suelen plantearla reformados.`,
    own:{lead:[`WCF2856`], more:[`WCF281`,`WLC165`,`WLC161`]},
    answer:[
      `Para la Iglesia católica, el bautismo es "el sacramento del nuevo nacimiento por el agua y la palabra" {c:CEC1213|Catecismo 1213}, y sus "dos efectos principales" son "la purificación de los pecados y el nuevo nacimiento en el Espíritu Santo" {c:CEC1262|Catecismo 1262}.`,
      `El Catecismo dice: "El Señor mismo afirma que el Bautismo es necesario para la salvación (cf Jn 3,5)" {c:CEC1257|Catecismo 1257}. Trento manda no torcer esas palabras "á algun sentido metafórico" {c:T7b2|ses. VII, Del bautismo, can. 2}. El Catecismo precisa para quiénes: "El Bautismo es necesario para la salvación en aquellos a los que el Evangelio ha sido anunciado y han tenido la posibilidad de pedir este sacramento"; y añade: "Dios ha vinculado la salvación al sacramento del Bautismo, sin embargo, Él no queda sometido a sus sacramentos" {c:CEC1257|Catecismo 1257}. Trento enseña que el paso a la gracia no se da "sin el Bautismo, ó sin el deseo de él" {c:T6c4|ses. VI, cap. 4}, y el Catecismo enseña el bautismo de sangre y el de deseo, que "produce los frutos del Bautismo sin ser sacramento" {c:CEC1258,CEC1259|Catecismo 1258–1259}. De quien, sin conocer el Evangelio, "busca la verdad y hace la voluntad de Dios según él la conoce", dice que "puede ser salvado" {c:CEC1260|Catecismo 1260}.`,
      `Sobre si todos los bautizados quedan regenerados, la Iglesia enseña que los sacramentos contienen la gracia que significan y la confieren "á los que no ponen obstáculo" {c:T7sacr6|Trento, ses. VII, De los sacramentos en general, can. 6}, y condena a quien diga "que no siempre, ni á todos se dá gracia por estos Sacramentos, en quanto está de parte de Dios, aunque los reciban dignamente" {c:T7sacr7|can. 7}. Los frutos "dependen también de las disposiciones del que los recibe" {c:CEC1128|Catecismo 1128}: el pecado puede impedir "al Bautismo dar frutos de salvación", aunque el sello bautismal permanece {c:CEC1272|Catecismo 1272}. Y de los niños dice Trento que "recibén con toda verdad el Bautismo en remision de sus pecados" {c:T5can4|ses. V, can. 4}.`,
      `El canon de Trento dice: "Si alguno dixere, que el Bautismo es arbitrario, esto es, no preciso para conseguir la salvacion; sea excomulgado" {c:T7b5|ses. VII, Del bautismo, can. 5}.`
    ],
    answerRv:{0:`Apertura del 2026-10-21: Catecismo 1213 y 1262. La respuesta ya no cita Juan 3:5 con la voz del sitio, sino la frase del Catecismo 1257.`, 1:`«Por eso Trento enseña» pasó a «Trento enseña» (verificación 2, G5).`, 2:`Corregido (verificación A9): se cita la proposición condenada del can. 7, no una paráfrasis positiva.`},
    fuentes:[
      {ids:`T5can4`, name:`Concilio de Trento, sesión V, can. 4`, date:`17 jun 1546`, year:1546},
      {ids:`T6c4`, name:`Concilio de Trento, sesión VI, cap. 4`, date:`13 ene 1547`, year:1547},
      {ids:`T7sacr6,T7sacr7,T7b2,T7b5`, name:`Concilio de Trento, sesión VII, De los sacramentos en general, cann. 6–7; Del bautismo, cann. 2 y 5`, date:`3 mar 1547`, year:1547},
      {ids:`CEC1128,CEC1213,CEC1257,CEC1258,CEC1259,CEC1260,CEC1262,CEC1272`, name:`Catecismo de la Iglesia Católica 1128, 1213, 1257–1260, 1262, 1272`, date:`1992/1997`, year:1992}
    ],
    pasajes:{resp:[`Juan 3:5`], obj:[`Hechos 8:13, 23`,`Lucas 7:30`,`Éxodo 4:24-26`,`Romanos 4:11`,`Hechos 10:2, 4, 22, 31, 45, 47`,`Juan 3:5, 8`,`Gálatas 3:27`,`Tito 3:5`,`Efesios 5:25-26`,`Hechos 2:38, 41`,`1 Pedro 3:21`,`1 Corintios 3:6-7`,`1 Corintios 12:13`,`Mateo 28:19-20`,`Colosenses 2:11-12`,`Romanos 6:3-5`,`Marcos 1:4`],
      objNote:`Textos de prueba de Westminster XXVIII.1, 5–6 y del Catecismo Mayor 161.`},
    rv:[`Cuatro textos (DECISIONS 2026-10-20): a la vista Westminster XXVIII.5–6, que dice la objeción entera en dos frases; en «ver más», XXVIII.1, Catecismo Mayor de Westminster 165 y 161.`,
        `Título revisado (experto 7): «El bautismo no es necesario para salvarse» decía más que Westminster XXVIII.5, que llama «grave pecado» descuidarlo.`,
        `Nota honesta del dosier (solo dosier, no línea de la página): el can. 5 condena llamar al bautismo «arbitrario»; Westminster no lo llama opcional, así que si el canon alcanza su posición no lo resuelven los documentos leídos, y la respuesta no lo afirma.`,
        `Los luteranos no la plantean: la Confesión de Augsburgo IX dice que el bautismo «es necesario para la salvación» y condena a quienes dicen que los niños se salvan sin él.`]},

  'OB-2': {title:`«Los sacramentos no dan la gracia por el solo rito realizado: sin la fe no aprovechan»`,
    syn:`Los sacramentos son signos y testimonios de la voluntad de Dios hacia nosotros, dados para despertar y confirmar la fe de quienes los usan: aprovechan cuando la fe cree la promesa que en ellos se ofrece. Enseñar que confieren la gracia "ex opere operato", por el solo hecho de realizarse, a quien no pone obstáculo, aunque no haya en él un buen movimiento del corazón, es creer que el hombre se justifica por una ceremonia, sin fe; Abraham no fue justificado por la circuncisión, que le fue dada como señal {v:Romanos 4:9-11}. Los reformados añaden que la gracia no la confiere ningún poder que esté en los sacramentos, sino solo la obra del Espíritu.`,
    who:`Suelen plantearla luteranos y reformados.`,
    own:{lead:[`AC13`], more:[`AP13`,`WCF273`,`LC4373`]},
    answer:[
      `Para la Iglesia católica, el bautismo es "el sacramento de la fe" {c:CEC1253|Catecismo 1253}, y los sacramentos "no sólo suponen la fe, también la fortalecen, la alimentan y la expresan" {c:CEC1123|Catecismo 1123, citando al Concilio Vaticano II}. "Celebrados dignamente en la fe", dice el Catecismo, "los sacramentos confieren la gracia que significan" {c:CEC1127|Catecismo 1127}. Trento describe cómo se prepara el adulto: "movidos y ayudados por la gracia divina, conciben la fe por el oido, y se inclinan libremente á Dios", esperan en su misericordia, "comienzan á amarle como fuente de toda justicia", se arrepienten "con aquel arrepentimiento que deben tener antes del Bautismo", y se proponen "recibir este sacramento, empezar una vida nueva, y observar los mandamientos de Dios" {c:T6c6|ses. VI, cap. 6} {v:Romanos 10:17}.`,
      `El Catecismo dice dónde está la eficacia de los sacramentos: "Son eficaces porque en ellos actúa Cristo mismo; Él es quien bautiza, Él quien actúa en sus sacramentos con el fin de comunicar la gracia que el sacramento significa. El Padre escucha siempre la oración de la Iglesia de su Hijo que, en la epíclesis de cada sacramento, expresa su fe en el poder del Espíritu" {c:CEC1127|Catecismo 1127}.`,
      `Para la Iglesia católica, "ex opere operato" quiere decir que el sacramento obra "en virtud de la obra salvífica de Cristo, realizada de una vez por todas", de modo que "el sacramento no actúa en virtud de la justicia del hombre que lo da o que lo recibe, sino por el poder de Dios"; y añade: "Sin embargo, los frutos de los sacramentos dependen también de las disposiciones del que los recibe" {c:CEC1128|Catecismo 1128}. Trento rechaza que los sacramentos sean "solo […] señales extrínsecas de la gracia ó santidad recibida por la fe" {c:T7sacr6|ses. VII, De los sacramentos en general, can. 6}.`,
      `El canon de Trento dice: "Si alguno dixere, que por los mismos Sacramentos de la nueva ley no se confiere gracia ex opere operato, sino que basta para conseguirla sola la fe en las divinas promesas; sea excomulgado" {c:T7sacr8|ses. VII, De los sacramentos en general, can. 8}.`
    ],
    answerRv:{0:`Apertura con «Para la Iglesia católica, …» (2026-10-21). Acentos de Trento VI cap. 6 corregidos según la imagen (verificación 2, A7).`, 2:`«Por eso Trento rechaza» pasó a «Trento rechaza» (verificación 2, G5).`},
    fuentes:[
      {ids:`T6c6`, name:`Concilio de Trento, sesión VI, cap. 6`, date:`13 ene 1547`, year:1547},
      {ids:`T7sacr6,T7sacr8`, name:`Concilio de Trento, sesión VII, De los sacramentos en general, cann. 6 y 8`, date:`3 mar 1547`, year:1547},
      {ids:`CEC1123,CEC1127,CEC1128,CEC1253`, name:`Catecismo de la Iglesia Católica 1123, 1127, 1128, 1253`, date:`1992/1997`, year:1992},
      {ids:`CEC1123`, name:`Concilio Vaticano II, Sacrosanctum Concilium 59 (vía Catecismo 1123)`, date:`4 dic 1963`, year:1963}
    ],
    pasajes:{resp:[`Romanos 10:17`,`Marcos 16:16`], obj:[`Romanos 4:9-11`,`Romanos 2:28-29`,`1 Pedro 3:21`,`Mateo 3:11`,`1 Corintios 12:13`,`Mateo 26:27-28`,`Mateo 28:19-20`,`Marcos 16:16`],
      objNote:`Textos de la Apología XIII.19 y textos de prueba de Westminster XXVII.3; el Catecismo Mayor IV.33 cita Marcos 16:16.`},
    pasajesRv:`Quitados el 2026-10-21: Hechos 8:13, 23 y 1 Corintios 3:6-7, textos de prueba del Catecismo Mayor de Westminster 161, que en OB-2 pasó a «también leído».`,
    rv:[`Cuatro textos: a la vista la Confesión de Augsburgo XIII; en «ver más», la Apología XIII.18–20, 23 (con su línea de estado actual), Westminster XXVII.3 y el Catecismo Mayor IV.33 y IV.73. También leído, no entre los cuatro: Catecismo Mayor de Westminster 161 (dice lo mismo que XXVII.3; está entre los cuatro de OB-1).`,
        `Los textos luteranos sostienen a la vez que el bautismo es «necesario y eficaz para la salvación», también en los niños (Apología IX.51): la objeción es sobre cómo dan la gracia los sacramentos, no sobre si el bautismo regenera.`,
        `Nota honesta del dosier (solo dosier): la Apología XIII condena la gracia «sin buena disposición»; Catecismo 1128 dice que los frutos dependen de las disposiciones, y Trento habla de quienes «no ponen obstáculo». Si coinciden no lo resuelven los documentos leídos: la respuesta deja ambos textos.`]},

  'DO-1': {title:`«Muéstreme en la Biblia un solo bebé bautizado» — Frecuente en el debate`,
    syn:`Todos los bautismos que registra el Nuevo Testamento son de personas que oyeron, creyeron y se arrepintieron; ningún texto muestra a un bebé bautizado. Lo que la Biblia no muestra no puede ser una práctica de la Iglesia.`,
    who:`Desde la tradición bautista y desde las Asambleas de Dios se objeta que el Nuevo Testamento no muestra el bautismo de ningún niño. Para los bautistas, "el bautismo cristiano es la inmersión de un creyente en agua" (Fe y Mensaje Bautistas, art. VII); para las Asambleas de Dios, "todos los que se arrepienten y creen en Cristo como Salvador y Señor deben ser bautizados" (Declaración de Verdades Fundamentales, 6).`,
    own:{lead:[`BFM7a`], more:[`AG6s`]},
    answer:[
      `El Catecismo dice: "La práctica de bautizar a los niños pequeños es una tradición inmemorial de la Iglesia. Está atestiguada explícitamente desde el siglo II. Sin embargo, es muy posible que, desde el comienzo de la predicación apostólica, cuando 'casas' enteras recibieron el Bautismo (cf Hch 16,15.33; 18,8; 1 Co 1,16), se haya bautizado también a los niños" {c:CEC1252|Catecismo 1252}.`,
      `El Catecismo cita el bautismo del carcelero de Filipos: "'Ten fe en el Señor Jesús y te salvarás tú y tu casa', declara san. Pablo [sic] a su carcelero en Filipos. El relato continúa: 'el carcelero inmediatamente recibió el bautismo, él y todos los suyos' (Hch 16,31-33)" {c:CEC1226|Catecismo 1226}.`,
      `Para la Iglesia católica, Trento enseña: "Y así por esta regla de fe, conforme á la tradicion de los Apóstoles, aun los párvulos que todavía no han podido cometer pecado alguno personal, recibén con toda verdad el Bautismo en remision de sus pecados" {c:T5can4|Trento, ses. V, can. 4}. El Catecismo dice: "Desde los tiempos más antiguos, el Bautismo es dado a los niños, porque es una gracia y un don de Dios que no suponen méritos humanos; los niños son bautizados en la fe de la Iglesia" {c:CEC1282|Catecismo 1282}.`,
      `_Respuesta apologética pendiente (capa de debate):_ el argumento de que ningún texto del Nuevo Testamento nombra el bautismo de un niño.`,
      `El canon de Trento dice: "Si alguno niega que los niños recien nacidos se hayan de bautizar, aunque sean hijos de padres bautizados […] sea excomulgado" {c:T5can4|ses. V, can. 4}.`
    ],
    answerRv:{0:`La fecha del siglo II va como palabras del Catecismo (Pregunta 12).`, 2:`Corregido (verificación 2, A2 y G3): ya no dice con voz del sitio que el bautismo de los niños sea «regla de fe»; cita la frase entera de Trento, con «conforme á» como en la impresión.`, 3:RV_PEND},
    fuentes:[
      {ids:`CEC1226,CEC1252,CEC1282`, name:`Catecismo de la Iglesia Católica 1226, 1252, 1282`, date:`1992/1997`, year:1992},
      {ids:`T5can4`, name:`Concilio de Trento, sesión V, can. 4`, date:`17 jun 1546`, year:1546}
    ],
    pasajes:{resp:[`Hechos 16:15, 31-33`,`Hechos 18:8`,`1 Corintios 1:16`], obj:[`Hechos 2:41-42`,`Hechos 8:35-39`,`Hechos 16:30-33`], objNote:`Textos de prueba de Fe y Mensaje Bautistas VII.`},
    rv:[RV_DEB, RV_LINE, `Dónde se plantea (ventana de fuentes, no va en la página): 7 independientes (6 sin el oyente que llama), F-1.`, `Anclas solo por inferencia: ninguna menciona a los niños. No se usaron las respuestas católicas de los debatientes (1 Corintios 10:1-2, «todas las naciones»): son apologética.`]},

  'DO-2': {title:`«Un bebé no puede creer ni arrepentirse: primero se cree, después se bautiza» — Frecuente en el debate`,
    syn:`En la Escritura el arrepentimiento, la fe y el discipulado van antes del bautismo: "El que creyere y fuere bautizado, será salvo" {v:Marcos 16:16}. Un bebé no puede arrepentirse ni creer; por eso no puede ser bautizado: primero se cree, después se bautiza.`,
    who:`Desde las Asambleas de Dios y desde la tradición bautista se objeta que el bautismo exige fe y arrepentimiento, que un bebé no puede tener. Para las Asambleas de Dios, "todos los que se arrepienten y creen en Cristo como Salvador y Señor deben ser bautizados" (Declaración de Verdades Fundamentales, 6); para los bautistas, el bautismo "simboliza la fe del creyente" (Fe y Mensaje Bautistas, art. VII).`,
    own:{lead:[`AG6s`], more:[`BFM7b`]},
    answer:[
      `Para la Iglesia católica, el adulto llega al bautismo por la fe y la conversión. Trento describe cómo se prepara: "movidos y ayudados por la gracia divina, conciben la fe por el oido, y se inclinan libremente á Dios", y se mueven contra el pecado "con aquel arrepentimiento que deben tener antes del Bautismo" {c:T6c6|ses. VI, cap. 6} {v:Hechos 2:38}. El Catecismo dice que el catecumenado de adultos tiene por finalidad "llevar a madurez su conversión y su fe" {c:CEC1248|Catecismo 1248}.`,
      `El Catecismo dice también: "El Bautismo es el sacramento de la fe (cf Mc 16,16). Pero la fe tiene necesidad de la comunidad de creyentes. Sólo en la fe de la Iglesia puede creer cada uno de los fieles. La fe que se requiere para el Bautismo no es una fe perfecta y madura, sino un comienzo que está llamado a desarrollarse" {c:CEC1253|Catecismo 1253}.`,
      `Del bautismo de los niños dice: "La pura gratuidad de la gracia de la salvación se manifiesta particularmente en el bautismo de niños" {c:CEC1250|Catecismo 1250}; "los niños son bautizados en la fe de la Iglesia" {c:CEC1282|Catecismo 1282}. Y añade: "Por su naturaleza misma, el Bautismo de niños exige un catecumenado postbautismal. No se trata sólo de la necesidad de una instrucción posterior al Bautismo, sino del desarrollo necesario de la gracia bautismal en el crecimiento de la persona" {c:CEC1231|Catecismo 1231}; "En todos los bautizados, niños o adultos, la fe debe crecer después del Bautismo" {c:CEC1254|Catecismo 1254}.`,
      `El canon de Trento dice: "Si alguno dixere, que los párvulos despues de recibido el Bautismo, no se deben contar entre los fieles, por quanto no hacen acto de fe, y que por esta causa se deben rebautizar quando lleguen á la edad y uso de la razon; ó que es mas conveniente dexar de bautizarles, que el conferirles el Bautismo en sola la fe de la Iglesia sin que ellos crean con acto suyo propio; sea excomulgado" {c:T7b13|ses. VII, Del bautismo, can. 13}.`
    ],
    answerRv:{3:`«párvulos» y «á la edad» como en la impresión (verificación 2, A8).`},
    fuentes:[
      {ids:`T6c6`, name:`Concilio de Trento, sesión VI, cap. 6`, date:`13 ene 1547`, year:1547},
      {ids:`T7b13`, name:`Concilio de Trento, sesión VII, Del bautismo, can. 13`, date:`3 mar 1547`, year:1547},
      {ids:`CEC1231,CEC1248,CEC1250,CEC1253,CEC1254,CEC1282`, name:`Catecismo de la Iglesia Católica 1231, 1248, 1250, 1253, 1254, 1282`, date:`1992/1997`, year:1992}
    ],
    pasajes:{resp:[`Hechos 2:38`,`Marcos 16:16`], obj:[`Marcos 16:16`,`Hechos 2:41`,`Hechos 8:35-39`,`Mateo 28:19`], objNote:`Textos de prueba de la Declaración 6 y de Fe y Mensaje Bautistas VII, y versículos citados en los debates.`},
    rv:[RV_DEB, RV_LINE, `Dónde se plantea (ventana de fuentes, no va en la página): 10 independientes (7 sin los oyentes que llaman) y 1 parcial (F-2).`, `Anclas solo por inferencia. No se usó «la fe del papá sirve para la familia», de un debatiente: pone la fe de los padres donde Catecismo 1253 y el can. 13 dicen «fe de la Iglesia».`]},

  'DO-4': {title:`«Los niños no tienen pecado: de ellos es el reino de los cielos» — Frecuente en el debate`,
    syn:`Un niño no ha cometido pecado: es inocente hasta que puede elegir. Jesús dijo que de los niños es el reino de los cielos; un niño que muere va con Cristo, esté bautizado o no, y un bautismo "para perdón de los pecados" no tiene nada que darle.`,
    who:`Desde la tradición bautista se objeta que los niños no tienen pecado que perdonar. Para los bautistas, la posteridad de Adán "heredó una naturaleza y un ambiente inclinado al pecado. Por tanto, tan pronto como son capaces de realizar una acción moral, se convierten en transgresores y están bajo condenación" (Fe y Mensaje Bautistas, art. III).`,
    own:{lead:[`BFM3`], more:[]},
    answer:[
      `El Catecismo dice: "Siguiendo a san Pablo, la Iglesia ha enseñado siempre que la inmensa miseria que oprime a los hombres y su inclinación al mal y a la muerte no son comprensibles sin su conexión con el pecado de Adán y con el hecho de que nos ha transmitido un pecado con que todos nacemos afectados y que es 'muerte del alma' (Concilio de Trento: DS 1512). Por esta certeza de fe, la Iglesia concede el Bautismo para la remisión de los pecados incluso a los niños que no han cometido pecado personal" {c:CEC403|Catecismo 403}. Y precisa: "Aunque propio de cada uno […], el pecado original no tiene, en ningún descendiente de Adán, un carácter de falta personal" {c:CEC405|Catecismo 405}.`,
      `Trento enseña que "aun los párvulos que todavía no han podido cometer pecado alguno personal, recibén con toda verdad el Bautismo en remision de sus pecados, para que purifique la regeneracion en ellos lo que contraxeron por la generacion" {c:T5can4|ses. V, can. 4} {v:Romanos 5:12}. El Catecismo dice: "Puesto que nacen con una naturaleza humana caída y manchada por el pecado original, los niños necesitan también el nuevo nacimiento en el Bautismo" {c:CEC1250|Catecismo 1250}.`,
      `Sobre los niños que mueren sin bautismo, el Catecismo dice: "la Iglesia sólo puede confiarlos a la misericordia divina, como hace en el rito de las exequias por ellos. En efecto, la gran misericordia de Dios, que quiere que todos los hombres se salven (cf 1 Tm 2,4) y la ternura de Jesús con los niños, que le hizo decir: 'Dejad que los niños se acerquen a mí, no se lo impidáis' (Mc 10,14), nos permiten confiar en que haya un camino de salvación para los niños que mueren sin Bautismo. Por esto es más apremiante aún la llamada de la Iglesia a no impedir que los niños pequeños vengan a Cristo por el don del santo Bautismo" {c:CEC1261|Catecismo 1261}.`,
      `El canon de Trento dice: "Si alguno niega que los niños recien nacidos se hayan de bautizar, aunque sean hijos de padres bautizados; ó dice, que se bautizan para que se les perdonen los pecados, pero que nada participan del pecado original de Adan, de que necesiten purificarse con el baño de la regeneracion para conseguir la vida eterna […] sea excomulgado" {c:T5can4|ses. V, can. 4}.`
    ],
    answerRv:{0:`Catecismo 405 citado sin su paréntesis «(cf. ibíd., DS 1513)».`, 2:`El limbo, que plantea un oyente, no está en la objeción aprobada; su estado para la Iglesia está en el hueco del mapa 5 (Comisión Teológica Internacional, 2007, no usada).`},
    fuentes:[
      {ids:`CEC403,CEC405,CEC1250,CEC1261`, name:`Catecismo de la Iglesia Católica 403, 405, 1250, 1261`, date:`1992/1997`, year:1992},
      {ids:`T5can4`, name:`Concilio de Trento, sesión V, can. 4`, date:`17 jun 1546`, year:1546}
    ],
    pasajes:{resp:[`Romanos 5:12`,`Marcos 10:14`,`1 Timoteo 2:4`], obj:[`Mateo 19:14`,`Salmos 51:5`,`Ezequiel 18:20`], objNote:`Versículos citados en los debates.`},
    rv:[RV_DEB, RV_LINE, `Título en inglés (BSB, Mateo 19:14): "Children have no sin: 'the kingdom of heaven belongs to such as these'". «de los niños» es la redacción de los debatientes; la RV1909 dice «de los tales es el reino de los cielos»: el versículo queda solo en Pasajes (verificación 2, C7).`, `Dónde se plantea (ventana de fuentes, no va en la página): 8 firmes (5 sin los oyentes que llaman) y 1 parcial (F-3).`, `Ancla solo por inferencia: el art. III dice cuándo empieza la condenación, no habla de la salvación de los niños ni del reino, y afirma una inclinación heredada al pecado. Ningún texto de las Asambleas de Dios la ancla: la página nombra solo a los bautistas (Pregunta 21).`]},

  'DO-6': {title:`«Bautizar es sumergir: un poquito de agua en la cabeza no es bautismo» — Frecuente en el debate`,
    syn:`Bautizar quiere decir sumergir; Jesús "subió luego del agua" {v:Mateo 3:16} y Felipe y el eunuco "descendieron ambos al agua" {v:Hechos 8:38}. El bautismo representa una sepultura, y nadie se entierra a medias: derramar un poco de agua sobre la cabeza no es el bautismo del Nuevo Testamento.`,
    who:`Desde la tradición bautista y desde las Asambleas de Dios se objeta que solo la inmersión es bautismo. Para los bautistas, "el bautismo cristiano es la inmersión de un creyente en agua" (Fe y Mensaje Bautistas, art. VII); para las Asambleas de Dios, "las Escrituras establecen la ordenanza del bautismo en agua por inmersión" (Declaración de Verdades Fundamentales, 6).`,
    own:{lead:[`BFM7a`], more:[`AG6m`]},
    answer:[
      `El Catecismo dice: "bautizar (baptizein en griego) significa 'sumergir', 'introducir dentro del agua'; la 'inmersión' en el agua simboliza el acto de sepultar al catecúmeno en la muerte de Cristo, de donde sale por la resurrección con Él (cf Rm 6,3-4; Col 2,12) como 'nueva criatura'" {c:CEC1214|Catecismo 1214}.`,
      `Y dice también: "El Bautismo es realizado de la manera más significativa mediante la triple inmersión en el agua bautismal. Pero desde la antigüedad puede ser también conferido derramando tres veces agua sobre la cabeza del candidato" {c:CEC1239|Catecismo 1239}. El Código de Derecho Canónico dice: "El bautismo se ha de administrar por inmersión o por infusión […]" {c:CIC854|can. 854}.`,
      `Para la Iglesia católica, "el rito esencial del Bautismo consiste en sumergir en el agua al candidato o derramar agua sobre su cabeza, pronunciando la invocación de la Santísima Trinidad" {c:CEC1278|Catecismo 1278}. El IV Concilio de Letrán dice que el bautismo "consagrado por la invocacion de la Trinidad […] sobre el agua" da la salvación "así á los niños como á los adultos" {c:LAT1|const. 1, 1215}.`,
      `_Respuesta apologética pendiente (capa de debate):_ la lectura de Mateo 3:16 y Hechos 8:38, y el testimonio de la Didaché.`,
      `El canon de Trento sobre la materia del bautismo dice: "Si alguno dixere, que el agua verdadera y natural no es necesaria para el Sacramento del Bautismo, y por este motivo torciere á algun sentido metafórico aquellas palabras de nuestro señor Jesu-Cristo: 'Quien no renaciere del agua, y del Espíritu Santo;' sea excomulgado" {c:T7b2|ses. VII, Del bautismo, can. 2}.`
    ],
    answerRv:{1:`El can. 854 termina «[…]»: se corta «de acuerdo con las normas de la Conferencia Episcopal» (verificación 2, B8).`, 2:RV_FLOLAT, 3:RV_PEND, 4:`El mismo final que OB-6a (la objeción ortodoxa sobre el modo): ningún canon define el modo.`},
    fuentes:[
      {ids:`CEC1214,CEC1239,CEC1278`, name:`Catecismo de la Iglesia Católica 1214, 1239, 1278`, date:`1992/1997`, year:1992},
      {ids:`CIC854`, name:`Código de Derecho Canónico, can. 854`, date:`1983`, year:1983},
      {ids:`LAT1`, name:`IV Concilio de Letrán, const. 1`, date:`1215`, year:1215},
      {ids:`T7b2`, name:`Concilio de Trento, sesión VII, Del bautismo, can. 2`, date:`3 mar 1547`, year:1547}
    ],
    pasajes:{resp:[`Romanos 6:3-4`,`Colosenses 2:12`], obj:[`Mateo 3:16`,`Hechos 8:38`,`Romanos 6:3-5`,`Colosenses 2:12`]},
    rv:[RV_DEB, RV_LINE, `Dónde se plantea (ventana de fuentes, no va en la página): 5 independientes (F-4).`, `No se usaron, por tensión con el can. 2 y con Catecismo 1239: «el agua pasa a ser solamente símbolo» y «la inmersión era el bautismo de Juan», de debatientes.`]},

  'OB-6a': {title:`«Rociar o derramar agua no es el bautismo apostólico: el bautismo es por tres inmersiones»`,
    syn:`La Iglesia de los siete concilios ecuménicos bautizaba con tres inmersiones en el agua, y así se practicó también en Occidente durante siglos, como muestran las antiguas pilas bautismales; la aspersión o la infusión, introducidas "a escondidas", son una innovación de la Iglesia papal. Lo esencial del bautismo es la triple inmersión con la invocación del Padre, del Hijo y del Espíritu Santo, figura de la sepultura y la resurrección de tres días.`,
    who:WHO_ORTH,
    own:{lead:[`ENC8`], more:[`MOG102`,`PHIL290`,`OROSa`]},
    answer:[
      `El Catecismo dice: "El Bautismo es realizado de la manera más significativa mediante la triple inmersión en el agua bautismal. Pero desde la antigüedad puede ser también conferido derramando tres veces agua sobre la cabeza del candidato" {c:CEC1239|Catecismo 1239}. El Código de Derecho Canónico dice: "El bautismo se ha de administrar por inmersión o por infusión […]" {c:CIC854|can. 854}. El Catecismo describe también el rito de las Iglesias orientales, donde el sacerdote, invocando a cada persona de la Trinidad, sumerge al catecúmeno en el agua y lo saca de ella {c:CEC1239|Catecismo 1240}.`,
      `Para la Iglesia católica, lo esencial del bautismo es el agua verdadera y la invocación de la Trinidad: "sumergir en el agua al candidato o derramar agua sobre su cabeza, pronunciando la invocación de la Santísima Trinidad" {c:CEC1278|Catecismo 1278}. Trento declara necesaria "el agua verdadera y natural" {c:T7b2|ses. VII, Del bautismo, can. 2}, y el IV Concilio de Letrán dice que el bautismo "consagrado por la invocacion de la Trinidad […] sobre el agua" da la salvación a niños y adultos {c:LAT1|1215}.`,
      `_Respuesta apologética pendiente (capa de debate):_ las afirmaciones históricas de la encíclica de 1895 sobre el papa Pelagio, la práctica occidental del siglo XIII y las pilas de las iglesias de Italia.`,
      `El canon de Trento sobre la materia del bautismo dice: "Si alguno dixere, que el agua verdadera y natural no es necesaria para el Sacramento del Bautismo, y por este motivo torciere á algun sentido metafórico aquellas palabras de nuestro señor Jesu-Cristo: 'Quien no renaciere del agua, y del Espíritu Santo;' sea excomulgado" {c:T7b2|ses. VII, Del bautismo, can. 2}.`
    ],
    answerRv:{0:`Can. 854 ahora citado en el primer párrafo, con «[…]» (verificación 2, B8). «con respeto» y el argumento desde el silencio sobre Florencia, quitados el 2026-10-18.`, 1:RV_FLOLAT, 2:`${RV_PEND} Reemplaza la línea «Los documentos católicos citados aquí no responden…» de la v1.`, 3:`Final: el can. 2 (DECISIONS 2026-10-20, Preguntas 9–10 de la Eucaristía: el canon que corresponde o el texto conciliar más cercano). Se quitaron la opción A (can. 3, sobre la Iglesia Romana) y la frase de voz del sitio «Ningún canon de Trento define el modo…».`},
    fuentes:[
      {ids:`CEC1239,CEC1278`, name:`Catecismo de la Iglesia Católica 1239–1240, 1278`, date:`1992/1997`, year:1992},
      {ids:`CIC854`, name:`Código de Derecho Canónico, can. 854`, date:`1983`, year:1983},
      {ids:`T7b2`, name:`Concilio de Trento, sesión VII, Del bautismo, can. 2`, date:`3 mar 1547`, year:1547},
      {ids:`LAT1`, name:`IV Concilio de Letrán, const. 1`, date:`1215`, year:1215}
    ],
    pasajes:{resp:[], obj:[`Mateo 28:19`,`Juan 3:5`], objNote:`Notas del Oros de 1755.`},
    pasajesRv:`Nota del dosier: Mogila, pregunta 102, cita Juan 3:5; la encíclica de 1895 (§VIII) y Filareto (pregunta 290) no imprimen textos de prueba en los pasajes citados.`,
    rv:[RV_WHO_ORTH,
        `Cuatro textos: a la vista la encíclica de 1895 §VIII (con su línea de estado actual); en «ver más», Mogila 102–103, Filareto 290 y el Oros de 1755 (con su línea de estado actual). También leídos, no entre los cuatro: §IV y §VI de la misma encíclica.`,
        `La encíclica de 1848 («sprinkling instead of baptism») queda solo en el dosier: inglés de procedencia sin probar (crítico 14).`]},

  'OB-6b': {title:`«Solo es bautismo el de la Iglesia ortodoxa: el de los herejes no santifica ni perdona los pecados»`,
    syn:`Hay una sola Iglesia, santa, católica y apostólica, y solo sus misterios, y por tanto su bautismo, se aceptan. Los ritos no administrados como el Espíritu Santo mandó a los Apóstoles son ajenos a la tradición apostólica: los bautismos de los herejes son "aguas inútiles", que no santifican ni lavan los pecados. Por eso a quienes vienen de ellos se los recibe como no bautizados y se los bautiza.`,
    who:WHO_ORTH,
    own:{lead:[`OROSb`], more:[`MOG102r`,`DOS16`]},
    answer:[
      `Para la Iglesia católica, es verdadero bautismo el que se da con agua y en el nombre del Padre, del Hijo y del Espíritu Santo, con la intención de hacer lo que hace la Iglesia: "En caso de necesidad, cualquier persona, incluso no bautizada, puede bautizar […] si tiene la intención requerida y utiliza la fórmula bautismal trinitaria" {c:CEC1256|Catecismo 1256}. El Concilio de Florencia lo dijo así: "en caso de necesidad puede bautizar no solo el sacerdote o el diácono, sino también un laico o una mujer, y aun un pagano y un hereje, con tal que observe la forma de la Iglesia y tenga intención de hacer lo que hace la Iglesia" {c:FLOexs|decreto para los armenios, 1439}; y el IV Concilio de Letrán, que el bautismo dado según la forma de la Iglesia "sea quien quiera el Ministro" da la salvación {c:LAT1|1215}. El Catecismo da la razón: "la voluntad salvífica universal de Dios (cf 1 Tm 2,4)" y "la necesidad del Bautismo para la salvación (cf Mc 16,16)" {c:CEC1256|Catecismo 1256}.`,
      `Para la Iglesia católica, "Los bautizados en una comunidad eclesial no católica no deben ser bautizados bajo condición, a no ser que haya un motivo serio para dudar de la validez de su bautismo" {c:CIC869|Código de Derecho Canónico, can. 869 §2}. El Concilio Vaticano II dice de "quienes creen en Cristo y recibieron el bautismo debidamente" que, "justificados por la fe en el bautismo", "justamente son reconocidos como hermanos en el Señor por los hijos de la Iglesia católica" {c:UR3|Unitatis redintegratio 3}.`,
      `El canon de Trento dice: "Si alguno dixere, que el Bautismo, aun el que confieren los hereges en el nombre del Padre, del Hijo y del Espíritu Santo, con intencion de hacer lo que hace la Iglesia, no es verdadero Bautismo; sea excomulgado" {c:T7b4|ses. VII, Del bautismo, can. 4}.`
    ],
    answerRv:{0:`${RV_FLO} ${RV_FLOLAT}`, 1:`Reescrito el 2026-10-21 (verificación 2, B9): el can. 869 §2 trata del bautismo bajo condición y se cita entero hasta «su bautismo»; «por eso» quitado; Unitatis redintegratio 3 con su sujeto.`},
    fuentes:[
      {ids:`T7b4`, name:`Concilio de Trento, sesión VII, Del bautismo, can. 4`, date:`3 mar 1547`, year:1547},
      {ids:`FLOexs`, name:`Concilio de Florencia, Exsultate Deo`, date:`22 nov 1439`, year:1439},
      {ids:`LAT1`, name:`IV Concilio de Letrán, const. 1`, date:`1215`, year:1215},
      {ids:`CEC1256`, name:`Catecismo de la Iglesia Católica 1256`, date:`1992/1997`, year:1992},
      {ids:`CIC869`, name:`Código de Derecho Canónico, can. 869 §2`, date:`1983`, year:1983},
      {ids:`UR3`, name:`Concilio Vaticano II, Unitatis redintegratio 3`, date:`21 nov 1964`, year:1964}
    ],
    pasajes:{resp:[`1 Timoteo 2:4`,`Marcos 16:16`], obj:[`Mateo 28:19`], objNote:`Nota del Oros de 1755.`},
    pasajesRv:`Nota del dosier: las otras notas del Oros citan Padres y cánones (Canon apostólico 50, Constantinopla I c. 7, Trullo c. 95).`,
    rv:[RV_WHO_ORTH,
        `Tres textos: a la vista el Oros de 1755 (con su línea de estado actual); en «ver más», Mogila 102 y Dositeo XVI. Dositeo XV ya no figura entre ellos: no es texto de objetor (verificación 2, D8).`,
        `Dositeo XVI y Mogila 102 exigen un ministro ortodoxo; Dositeo XV queda en el dosier como texto leído, no como texto de objetor.`]},

  'OB-4': {title:`«Volver a la penitencia es volver al bautismo: la "segunda tabla" no significa que el barco se haya roto»`,
    syn:`El bautismo no es algo pasado que se pierde al pecar: su poder y su significado abarcan toda la vida, y el arrepentimiento no es otra cosa que volver al bautismo y practicar de nuevo lo que en él se empezó. Por eso no es correcto llamar a la penitencia "segunda tabla" para nadar después del naufragio, como si el bautismo ya no sirviera: el barco no se rompe, porque es obra de Dios; somos nosotros los que caemos de él, y quien cae debe volver a él.`,
    who:`Suelen plantearla luteranos.`,
    own:{lead:[`LC4`], more:[]},
    answer:[
      `Para la Iglesia católica, el bautismo deja un sello que ningún pecado borra y que no se repite {c:CEC1272|Catecismo 1272} {c:T7sacr9|Trento, ses. VII, De los sacramentos en general, can. 9}. La conversión del bautizado es "una tarea ininterrumpida para toda la Iglesia", una "segunda conversión" {c:CEC1428|Catecismo 1428}; el bautismo es "el lugar principal de la conversión primera y fundamental" {c:CEC1427|Catecismo 1427} y "el primero y principal sacramento del perdón de los pecados" {c:CEC977|Catecismo 977}. El Catecismo, citando a Trento, también llama a la penitencia, con los Padres, "un bautismo laborioso": "Los Padres tuvieron razón en llamar a la penitencia 'un bautismo laborioso' (San Gregorio Nacianceno, Oratio 39, 17)" {c:CEC980|Catecismo 980} (el discurso, de 379–383).`,
      `Para la Iglesia católica, la Penitencia es un sacramento distinto del bautismo. Trento da las razones: difieren en la materia y la forma; el ministro de la Penitencia es juez, y a los que ya son miembros de su cuerpo Cristo "no quiso que si estos despues se contaminasen con alguna culpa, se purificáran repitiendo el Bautismo", sino que se presentaran ante este tribunal "no sola una vez, sino quantas recurriesen à él arrepentidos"; y "uno es el fruto del Bautismo, y otro el de la Penitencia": por el bautismo se recibe "plena y entera remision de los pecados", y a esa renovación no se llega por la Penitencia "sin muchas lágrimas y trabajos de nuestra parte" {c:T14c2|ses. XIV, cap. 2}. En otro canon, Trento condena la idea de que los pecados cometidos después del bautismo se perdonen "con solo el recuerdo, y fe del Bautismo recibido" {c:T7b10|ses. VII, Del bautismo, can. 10}. El Catecismo dice: "Los Padres de la Iglesia presentan este sacramento como 'la segunda tabla (de salvación) después del naufragio que es la pérdida de la gracia'" ({c:CEC1446|Catecismo 1446}, que remite a Trento y a Tertuliano, _De paenitentia_ 4, 2, c. 203).`,
      `_Respuesta apologética pendiente (capa de debate):_ si el canon 10 de la sesión VII alcanza la vuelta diaria al bautismo que enseña el Catecismo Mayor (IV.65, 79), dado que los luteranos conservan la absolución como sacramento (Apología XIII.4).`,
      `El canon de Trento dice: "Si alguno, confundiendo los Sacramentos, dixere, que el Bautismo es el mismo Sacramento de la Penitencia, como si estos dos Sacramentos no fuesen distintos; y que por lo mismo no se dá con propiedad à la Penitencia el nombre de segunda tabla despues del naufragio; sea excomulgado" {c:T14can2|ses. XIV, De la Penitencia, can. 2}.`
    ],
    answerRv:{0:`Corregido (verificación 2, G6): sin el «y que» colgante y sin la ruta del mapa dentro del texto; la fecha del discurso de Gregorio va una vez.`, 1:`Fecha de Tertuliano (Pedro, 2026-10-20): «c. 203» confirmado solo dentro del rango 198–204 de las ediciones. Catecismo 1446 se cita desde sus primeras palabras: la atribución a los Padres es del Catecismo.`, 2:`${RV_PEND} Reemplaza la frase de la v1 «si ese canon alcanza … los textos citados aquí no lo dicen».`},
    fuentes:[
      {ids:`T7sacr9,T7b10`, name:`Concilio de Trento, sesión VII, De los sacramentos en general, can. 9; Del bautismo, can. 10`, date:`3 mar 1547`, year:1547},
      {ids:`T14c2,T14can2`, name:`Concilio de Trento, sesión XIV, cap. 2, can. 2`, date:`25 nov 1551`, year:1551},
      {ids:`CEC977,CEC980,CEC1272,CEC1427,CEC1428,CEC1446`, name:`Catecismo de la Iglesia Católica 977, 980, 1272, 1427, 1428, 1446`, date:`1992/1997`, year:1992}
    ],
    pasajes:{resp:[`1 Corintios 5:12`], obj:[], respNote:`Citado por Trento, ses. XIV, cap. 2.`},
    pasajesRv:`El Catecismo Mayor no imprime textos de prueba en IV.74–86: no hay pasajes de la objeción.`,
    rv:[`Un texto en dos lenguas (el dosier lo marca así): Catecismo Mayor IV.74–82, 86, con el ¶65; en 04 se ve el ¶80–82 (alemán y su español) y el resto se lee al abrir la fuente.`,
        `Título revisado (crítico 11): el Catecismo Mayor dice que la imagen «no es correcta, o al menos no bien entendida».`,
        `Los luteranos conservan la absolución como sacramento (Apología XIII.4): la objeción es a la «segunda tabla» y a separar la penitencia del bautismo, no a la confesión.`,
        `El Catecismo 1446 atribuye la imagen a Tertuliano; el Catecismo Mayor, a san Jerónimo. Quién la acuñó no es la disputa.`]},

  'OB-3': {title:`«Solo un ministro de la Palabra legítimamente ordenado puede bautizar»`,
    syn:`Ni el bautismo ni la Cena del Señor pueden ser administrados sino por un ministro de la Palabra legítimamente ordenado, porque Cristo dio el mandato de bautizar a quienes envió a enseñar {v:Mateo 28:19} y nadie toma para sí este honor si no es llamado por Dios {v:Hebreos 5:4}. Y la eficacia del sacramento no depende de la piedad ni de la intención de quien lo administra, sino de la obra del Espíritu y de la palabra de la institución.`,
    who:`Suelen plantearla reformados.`,
    own:{lead:[`WCF274`], more:[`WCF282`,`WCF273`]},
    answer:[
      `Para la Iglesia católica, no todos los cristianos tienen potestad para administrar todos los sacramentos {c:T7sacr10|Trento, ses. VII, De los sacramentos en general, can. 10}; los ministros ordinarios del bautismo son el obispo, el presbítero y, en la Iglesia latina, el diácono {c:CEC1256|Catecismo 1256}.`,
      `Para la Iglesia católica, en caso de necesidad puede bautizar cualquiera. El Concilio de Florencia lo dijo así: "en caso de necesidad puede bautizar no solo el sacerdote o el diácono, sino también un laico o una mujer, y aun un pagano y un hereje, con tal que observe la forma de la Iglesia y tenga intención de hacer lo que hace la Iglesia" {c:FLOexs|decreto para los armenios, 1439}; y el IV Concilio de Letrán, que el bautismo dado según la forma de la Iglesia "sea quien quiera el Ministro" da la salvación {c:LAT1|1215}. El Catecismo da la razón: "la voluntad salvífica universal de Dios (cf 1 Tm 2,4)" y "la necesidad del Bautismo para la salvación (cf Mc 16,16)" {c:CEC1256|Catecismo 1256}.`,
      `Para la Iglesia católica, "el sacramento no actúa en virtud de la justicia del hombre que lo da o que lo recibe, sino por el poder de Dios" {c:CEC1128|Catecismo 1128} {c:T7sacr12|Trento, ses. VII, De los sacramentos en general, can. 12}; y "la intención requerida consiste en querer hacer lo que hace la Iglesia al bautizar" {c:CEC1256|Catecismo 1256}.`,
      `El canon de Trento sobre el ministro dice: "Si alguno dixere, que no se requiere en los ministros quando celebran, ó confieren los Sacramentos, intencion de hacer por lo menos lo mismo que hace la Iglesia; sea excomulgado" {c:T7sacr11|ses. VII, De los sacramentos en general, can. 11}.`
    ],
    answerRv:{0:`Corregido (verificación 2, G6): sin el «y que» colgante.`, 1:`${RV_FLO} ${RV_FLOLAT}`, 2:`Reescrito el 2026-10-21 con Catecismo 1128 y 1256 citados; se quitó «Ningún canon de Trento define quién puede bautizar…» (voz del sitio).`, 3:`Final: can. 11, que responde a Westminster XXVII.3 (Pregunta 8 resuelta: el canon que corresponde).`},
    fuentes:[
      {ids:`T7sacr10,T7sacr11,T7sacr12`, name:`Concilio de Trento, sesión VII, De los sacramentos en general, cann. 10–12`, date:`3 mar 1547`, year:1547},
      {ids:`FLOexs`, name:`Concilio de Florencia, decreto para los armenios Exsultate Deo`, date:`22 nov 1439`, year:1439},
      {ids:`LAT1`, name:`IV Concilio de Letrán, const. 1`, date:`1215`, year:1215},
      {ids:`CEC1128,CEC1256`, name:`Catecismo de la Iglesia Católica 1128, 1256`, date:`1992/1997`, year:1992}
    ],
    pasajes:{resp:[`1 Timoteo 2:4`,`Marcos 16:16`], obj:[`Mateo 28:19-20`,`1 Corintios 11:20, 23`,`1 Corintios 4:1`,`Hebreos 5:4`,`Mateo 3:11`,`Juan 1:33`], objNote:`Textos de prueba de Westminster XXVII.4 y XXVIII.2.`},
    rv:[`Tres textos: a la vista Westminster XXVII.4; en «ver más», XXVIII.2 y XXVII.3.`,
        `Bajo la regla del 2026-10-20, XXVII.4 es una frase exclusiva como Fe y Mensaje Bautistas VII; OB-3 se mantiene porque XXVII.3 niega en palabras lo que define el can. 11 (Pregunta 18, abierta).`,
        `Los textos de Westminster no dan excepción por necesidad.`]},

  'OB-5': {title:`«Lo que queda en el bautizado es verdadero pecado»`,
    syn:`El bautismo quita la culpa del pecado original, pero la concupiscencia que queda en el bautizado es verdadero pecado, aunque Dios lo perdone y no lo impute: Pablo la llama "pecado" {v:Romanos 7:7, 17, 20, 23}. Por eso la corrupción de la naturaleza permanece aun en los regenerados, y ella y todos sus movimientos son, dicen los reformados, "verdadera y propiamente pecado".`,
    who:`Suelen plantearla luteranos y reformados.`,
    own:{lead:[`AP2`], more:[`WCF65`]},
    answer:[
      `Para la Iglesia católica, por la gracia que se confiere en el bautismo se perdona el pecado original y "se quita todo lo que es propia y verdaderamente pecado", porque "Dios por cierto nada aborrece en los que han renacido" {c:T5can5|Trento, ses. V, can. 5} {v:Romanos 8:1}. El Catecismo lo dice así: "en los que han sido regenerados no permanece nada que les impida entrar en el Reino de Dios" {c:CEC1263|Catecismo 1263}.`,
      `Para la Iglesia católica, en el bautizado queda la concupiscencia, "dejada para el combate", que "no puede dañar a los que no la consienten y la resisten con coraje por la gracia de Jesucristo" {c:CEC1264|Catecismo 1264, citando a Trento}, y que permanece "a fin de que sirva de prueba en ellos en el combate de la vida cristiana" {c:CEC1426|Catecismo 1426}. El Catecismo lo dice también así: "El Bautismo, dando la vida de la gracia de Cristo, borra el pecado original y devuelve el hombre a Dios, pero las consecuencias para la naturaleza, debilitada e inclinada al mal, persisten en el hombre y lo llaman al combate espiritual" {c:CEC405|Catecismo 405}. Trento explica por qué Pablo la llama pecado: no "porque sea verdadera y propiamente pecado en los renacidos por el Bautismo; sino porque dimana del pecado, é inclina à él" {c:T5can5|ses. V, can. 5}.`,
      `El canon de Trento dice: "Si alguno niega que se perdona el reato del pecado original por la gracia de nuestro señor Jesu-Cristo que se confiere en el Bautismo; ó afirma que no se quita todo lo que es propia y verdaderamente pecado; sino dice, que este solamente se rae, ó dexa de imputarse; sea excomulgado" {c:T5can5|ses. V, can. 5}.`
    ],
    answerRv:{1:`Catecismo 405 añadido el 2026-10-21. «inclina à él»: acento como en el OCR; la imagen de la página no se leyó (verificación 2, A11).`},
    fuentes:[
      {ids:`T5can5`, name:`Concilio de Trento, sesión V, can. 5`, date:`17 jun 1546`, year:1546},
      {ids:`CEC405,CEC1263,CEC1264,CEC1426`, name:`Catecismo de la Iglesia Católica 405, 1263, 1264, 1426`, date:`1992/1997`, year:1992}
    ],
    pasajes:{resp:[`Romanos 8:1`,`2 Timoteo 2:5`], obj:[`Romanos 7:7`,`Romanos 7:14`,`Romanos 7:17`,`Romanos 7:18`,`Romanos 7:20`,`Romanos 7:23`]},
    rv:[`Dos textos: a la vista la Apología II; en «ver más», Westminster VI.5.`,
        `Repite OB-3 de Justificación con los mismos textos; va aquí porque la respuesta de Trento es un canon sobre el bautismo. ¿Una página enlazada desde las dos, o dos páginas? Pregunta 7.`,
        `La Declaración conjunta de 1999 y su Anexo hablan de esta objeción; se dejan a la página de Justificación, con la etiqueta «acuerdo ecuménico».`,
        `Textos de los objetores tomados del dosier de Justificación, no releídos aquí (salvo Westminster VI.5).`]}
};

const OB_LIST_NOTE = `Los textos que hablan por los bautistas en Doctrina definen el bautismo cristiano como "la inmersión de un creyente en agua" (Fe y Mensaje Bautistas, art. VII), y las Asambleas de Dios establecen "la ordenanza del bautismo en agua por inmersión" (Declaración de Verdades Fundamentales, 6). Las objeciones que de ahí se plantean en el debate están en esta misma lista, marcadas "Frecuente en el debate".`;

const QUESTIONS = [
  {n:4, t:`La Segunda Confesión de Londres (1689)`, ctx:`Dice en palabras lo que Fe y Mensaje Bautistas solo implica: los creyentes son «los únicos sujetos apropiados» (29.2) y la inmersión «es necesaria» (29.4). OB-7 salió de la lista oficial el 2026-10-21; su terreno lo cubren DO-1, DO-2 y DO-6, anclados en Fe y Mensaje Bautistas.`, opts:[`Dejarla fuera (DECISIONS 2026-10-15)`,`Mostrarla como contexto bajo OB-7`], rec:`Dejarla fuera de la columna, como se decidió; solo en el dosier.`, rel:[[`#do-1`,`DO-1`],[`#do-2`,`DO-2`],[`#do-6`,`DO-6`]]},
  {n:5, t:`Línea ortodoxa en la pantalla 04`, ctx:`Desde el 2026-10-21 dice solo el Oros de 1755 y su estado, «contested». La diversidad de práctica que oponía Dositeo XV al Oros era inferencia del sitio y salió (verificación 2, D8); Constantinopla 1484 y Moscú 1667 siguen fuera hasta leerlos en una edición (crítico 13).`, opts:[`Mantener la línea en 04`,`Solo en la columna ortodoxa`], rec:`Mantener la línea en 04; la diversidad de práctica va a la columna ortodoxa, con 1484 y 1667, cuando se lea Karmiris o el Tomos de 1698.`, rel:[[`#ob-6a`,`OB-6a`],[`#ob-6b`,`OB-6b`]]},
  {n:6, t:`Dónde aparece el acuerdo (crítico 18)`, ctx:`Augsburgo IX, Apología IX.51, Westminster XXVIII.3–4 y 7 y Dositeo XVI coinciden con QE-3, QE-4, QE-6 y QE-8; en la página católica luteranos y reformados aparecen solo como objetores.`, opts:[`shared.md`,`Pantalla 02, por afirmación`,`Una línea «Comparten este punto…» por afirmación en 03`], rec:`shared.md por afirmación (como en los pilotos); si la pantalla 02 no lo lleva, la línea en 03. Buscar en la Fórmula de Concordia XII antes de escribir shared.md.`, rel:[[`#p03/ensena`,`Qué enseña`]]},
  {n:7, t:`OB-5 repite OB-3 de Justificación (concupiscencia)`, ctx:`Mismos textos de los objetores; la respuesta de Trento es un canon sobre el bautismo.`, opts:[`Una página enlazada desde las dos`,`Dos páginas`], rec:`Una página bajo Bautismo (Trento V can. 5 es un canon sobre el bautismo), enlazada desde Justificación; el experto coincide.`, rel:[[`#ob-5`,`OB-5`]]},
  {n:9, t:`Frase de cierre de Por qué`, ctx:`Redactada con Trento V can. 4 (nombra el punto de los niños). Nota del 2026-10-21: con la Pregunta 2 resuelta, el punto de los niños está en 04 por DO-1, DO-2 y DO-4.`, opts:[`Trento V can. 4 (redactada)`,`Catecismo 1257: «Dios ha vinculado la salvación al sacramento del Bautismo, sin embargo, Él no queda sometido a sus sacramentos»`,`Catecismo 1213`], rec:`Con el punto de los niños en la página, Trento V can. 4 o Catecismo 1257 son honestas; el experto prefiere 1257, lo que la Iglesia pone en el centro (crítico 22).`, rel:[[`#p03/porque`,`Por qué`]]},
  {n:10, t:`Español hecho con IA`, ctx:`Florencia, Vienne, la encíclica de 1895, el Oros, Mogila, Dositeo, el Catecismo Mayor de Westminster 161 y 165, los textos luteranos.`, opts:[`Mantener, rotulado (hecho)`], rec:`Mantener; rehacer los ortodoxos desde el griego y los luteranos desde el latín o el alemán de 1921 cuando se construyan esas columnas.`, rel:[]},
  {n:12, t:`«Atestiguada explícitamente desde el siglo II» (Catecismo 1252)`, ctx:`Es la afirmación histórica de la Iglesia. Ahora aparece también en la respuesta a DO-1.`, opts:[`Mostrarla, citada y atribuida (hecho en QE-4 y DO-1)`,`Dejarla fuera`], rec:`Mostrarla atribuida; el experto coincide.`, rel:[[`#p03/ensena`,`Qué enseña, QE-4`],[`#do-1`,`DO-1`]]},
  {n:13, t:`QE-11 en la lista por defecto`, ctx:`El experto (1): la incorporación y el sacerdocio común son un efecto primario, no «ver más». La pantalla 03 muestra cinco por defecto.`, opts:[`Seis por defecto (QE-1, QE-2, QE-11, QE-3, QE-4, QE-5)`,`Cinco, pasando QE-5 o QE-4 a «ver más»`], rec:`Seis para esta doctrina: las objeciones apuntan a QE-3 a QE-5 y ninguna debería quedar oculta. Esta revisión ya muestra seis.`, rel:[[`#p03/ensena`,`Qué enseña`]]},
  {n:14, t:`Huecos del mapa (§8)`, ctx:`1 Pastoralis actio (1980; su fórmula de aprobación ya se leyó el 2026-10-21 en el texto alemán oficial: aprobada por Juan Pablo II, 20 oct 1980); 2 la nota de la Congregación de 2020 sobre la fórmula; 3 Gestis verbisque en la fila de Bautismo; 4 el griego del Oros de 1755; 5 Comisión Teológica Internacional (2007) sobre los niños que mueren sin bautismo; 6 Florencia, Cantate Domino (1442); 7 Pablo VI, Divinae consortium naturae (1971).`, opts:[`Aprobar`,`Esperar`], rec:`Aprobar 1, 3, 4 y 5; la CTI 2007 solo como nota de «ver más» bajo QE-3 con su fórmula de aprobación, nunca como grado (el experto); esperar 2, 6 y 7 hasta leerlos.`, rel:[[`#p03/ensena`,`Qué enseña, QE-3`],[`#do-1`,`DO-1`]]},
  {n:15, t:`Código, can. 868 §2 en CV-1`, ctx:`Bautismo de un niño en peligro de muerte «aun contra la voluntad de sus padres». Los revisores no coinciden.`, opts:[`Añadirlo, citado como ley, sin comentario (experto 15)`,`Dejar CV-1 como la ley ordinaria (rechazo del crítico)`], rec:`Dejarlo fuera mientras CV-1 diga el consentimiento de los padres solo como condición para bautizar lícitamente («Para bautizarlo lícitamente…», como ahora); añadir el §2 si CV-1 se acorta a «con el consentimiento de los padres».`, rel:[[`#p03/vive`,`Cómo se vive`]]},
  {n:17, t:`New Hampshire XIV en el sitio`, ctx:`El texto de 1853 es una reconstrucción del agente; el texto base «may not be the exact original text» (verificación D4). Desde el 2026-10-21 las objeciones del debate se anclan solo en Fe y Mensaje Bautistas, como se recomienda.`, opts:[`Mostrar la reconstrucción, rotulada`,`Fe y Mensaje Bautistas sola en 04 hasta leer una impresión de 1853`], rec:`Fe y Mensaje Bautistas sola (crítico 23); New Hampshire queda en el dosier.`, rel:[[`#do-1`,`DO-1`]]},
  {n:18, t:`OB-3 bajo la regla de la capa oficial`, ctx:`Westminster XXVII.4 («ni el uno, ni el otro de los cuales debe administrarse, sino por un ministro de la palabra legalmente ordenado») es una frase positiva exclusiva, como Fe y Mensaje Bautistas VII; OB-3 se apoya también en Westminster XXVII.3, que niega en palabras lo que define Trento VII, De los sacramentos en general, can. 11.`, opts:[`Mantener OB-3 en la capa oficial (aplicado)`,`Pasarla a la capa de debate (necesitaría evidencia de debates)`,`Quitarla`], rec:`Mantenerla, por Westminster XXVII.3.`, rel:[[`#ob-3`,`OB-3`]]},
  {n:19, t:`Orden de la lista única`, ctx:`Propuesto por tema, con objeciones oficiales y del debate lado a lado: DO-3, DO-5, DO-7, OB-1 (si salva y es necesario), OB-2 (cómo da la gracia), DO-1, DO-2, DO-4 (los niños), DO-6, OB-6a (el modo), OB-6b, OB-4, OB-3, OB-5. Dentro de cada tema, primero las que más se escuchan; OB-5 al final porque repite Justificación. Esta revisión ya lo muestra así.`, opts:[`Aceptar`,`Primero las oficiales, después las del debate`], rec:`Por tema (DECISIONS 2026-10-20: una sola lista, nunca secciones separadas).`, rel:[[`#p03/objeciones`,`Objeciones`]]},
  {n:20, t:`DO-5 en la pantalla 04`, ctx:`Una objeción con seis versículos dentro, en tabla (versículo, relectura, respuesta). El sexto, Tito 3:5, va más allá de los cinco que Pedro nombró en DECISIONS 2026-10-20 y se apoya en un solo debatiente (Barragán, 0:37:40): mantenerlo o quitarlo está abierto. Las celdas de relectura son síntesis neutrales del agente sobre lo que dicen los debatientes, introducidas «Desde la tradición bautista se lee…». En esta maqueta la tabla va como pares de párrafos.`, opts:[`Aceptar como está redactada`,`Citar a un debatiente por versículo, solo en la ventana de fuentes (como ahora)`], rec:`Aceptar como está redactada.`, rel:[[`#do-5`,`DO-5`]]},
  {n:21, t:`DO-4 nombra solo la tradición bautista`, ctx:`Ningún texto de las Asambleas de Dios ancla «los niños no tienen pecado» (Verdades Fundamentales 4–5 no hablan de los niños), aunque debatientes pentecostales la plantean.`, opts:[`Solo bautista (aplicado: la regla del ancla)`,`Nombrar las dos`], rec:`Solo bautista.`, rel:[[`#do-4`,`DO-4`]]}
];

const WEAK = [
  `Sin confirmar en la verificación 2: el español de Florencia (Exsultate Deo) y de Letrán IV (A15, confirmado solo en la primera verificación); «inclina à él» (Trento V can. 5) y «recurriesen à él» (XIV cap. 2), acentos del OCR, imágenes no leídas (A11, A12); el latín de XIV can. 2, con ortografía normalizada (A13); los subtítulos de los debates, cotejados solo con los archivos de evidencia; la impresión de Westminster de 1647 y el español de 1880 (solo se cotejó la ortografía moderna de opc.org).`,
  `Fechas de los Padres: tan buenas como los mapas neutrales. Gregorio Nacianceno (379–383), sin etiqueta allí; Agustín, sin fecha propia para el Tratado 80 y la Carta 98 (solo el rango 386–430); Tertuliano, De paenitentia, 198–204 en las ediciones («c. 203» solo dentro del rango); Justino (148–161) e Ireneo (177–200), con las fechas más estrechas sin confirmar.`,
  `Líneas de estado actual: ST-OROS descansa solo en el Oros y el mapa ortodoxo, sin búsqueda de un acto sinodal que lo retire o reafirme; ST-AP, sin búsqueda de una declaración luterana que matice la Apología XIII.18–23; ST-1895, el «no se encontró una retractación» descansa en wave-1-open-checks.`,
  `Capa de debate: citas, tiempos, cuentas y afiliaciones salen de debate-objections/spanish-debates.md y baptist-ag-2.md (subtítulos automáticos leídos el 2026-10-20); los nombres «Miguel», «Gusti» y «Anita» se infieren del presentador; los tiempos de Isaac Fuentes son del video de reacción.`,
  `Respuestas apologéticas pendientes (marcadas en las respuestas, para la investigación de debate): OB-4 (can. 10 y la vuelta diaria al bautismo del Catecismo Mayor), OB-6a (las afirmaciones históricas de 1895), DO-1 (ningún texto del Nuevo Testamento nombra un niño bautizado), DO-5 (eis en Hechos 2:38; «no quitando las inmundicias de la carne»; la segunda mitad de Marcos 16:16 y el final largo; 1 Corintios 1:17), DO-6 (Mateo 3:16, Hechos 8:38, la Didaché), DO-7 (el ladrón, Cornelio, el paralítico, el publicano).`,
  `Leído solo por el agente del paso de correcciones del 2026-10-18, sin verificador independiente: Catecismo 1212, 1267–1270, 1273, 1275, 1306; Lumen gentium 10, 11, 16; Código 842, 857, 861 §1, 868; las impresiones de la Triglotta de 1921 (latín y alemán); Fe y Mensaje Bautistas VI; McGlothlin pp. 305–306.`,
  `Español hecho con IA, sin revisar por Pedro: Florencia, Vienne, la encíclica de 1895, el Oros, Mogila, Dositeo, el Catecismo Mayor de Westminster 161 y 165, Augsburgo XIII, la Apología, el Catecismo Mayor; y los verbos citados en la línea ST-AP.`,
  `Grados por inferencia: cada línea «Dogma … la Iglesia no lo ha clasificado por separado» descansa en la lectura del agente de los cánones de Trento; solo QE-1 y QE-5 (can. 6) y los cánones sobre el pecado original están dentro de la lista de la Congregación (1998).`,
  `Cobertura ortodoxa escasa: no se leyeron Filareto más allá de la pregunta 290, el griego del Oros (Mansi 38), el rito de 1484 y las actas de Moscú 1667, ni Trullo c. 95 y Constantinopla I c. 7.`,
  `Nota de esta maqueta sobre el dosier: los textos de los versículos en Pasajes son de la RV1909 completa del archivo que fija el dosier; el dosier solo transcribe fragmentos.`
];

